def fill_rectangles(grid):
    result = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    bars = []
    for r in range(rows):
        i = 0
        while i < cols:
            if grid[r][i] == 5:
                start = i
                while i < cols and grid[r][i] == 5:
                    i += 1
                bars.append((r, start, i - 1))
            else:
                i += 1

    valid_bars = [(r, s, e) for r, s, e in bars if e - s + 1 >= 3]

    found = []
    for i, (r1, c1_s, c1_e) in enumerate(valid_bars):
        for r2, c2_s, c2_e in valid_bars[i+1:]:
            if c1_e - c1_s + 1 == c2_e - c2_s + 1:
                height = abs(r2 - r1) + 1
                if height >= 4:
                    left_ok = all(grid[r][c1_s] == 5 for r in range(r1, r2 + 1))
                    right_ok = all(grid[r][c2_e] == 5 for r in range(r1, r2 + 1))
                    if left_ok and right_ok:
                        found.append((r1, r2, c1_s, c2_e))
                        for r in range(r1 + 1, r2):
                            for c in range(c1_s + 1, c2_e):
                                if grid[r][c] == 9:
                                    result[r][c] = 5

    rect_result = result
    return rect_result, found, valid_bars

